import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {readdirSync,lstatSync,readFileSync,realpathSync,mkdirSync,writeFileSync,existsSync} from 'node:fs';import {join,resolve,relative,dirname,isAbsolute} from 'node:path';import {fileURLToPath} from 'node:url';
export const sha=b=>createHash('sha256').update(b).digest('hex');
export const bases=Object.freeze({V30:{manifest:'564a5fc19b479931a616a3ce0fdc8f1c02b71b072fb84d9683cb5147029bf7f6',app:'b736e11af8c527f497a1c975e1479aa3f6c5b7204fd8b6c44cc098921060d56d'},V33:{manifest:'137cc1cdc1dc783fa4cedadf3e16619a07c9cfa6f6559cb8d2f449b7603120db',app:'6d1358ee1dd1991a8307dee28a42ffcf617e0af073533a23820f94c630c2bfe5'}});
export const INDEX='51e08577d212f9d8f90095ada1d2acd2e6a373d3f9d8e875e8833e107c06dea4';
export const FILTER_HOOK="  try{const {mountProductFilters}=await import('./product-filters.mjs');mountProductFilters(document,{achievement:onAchievementsFilter,collection:renderCollections});}catch{}\n";
export function patchFilters(bytes,version){const pin=bases[version];assert.ok(pin);assert.equal(sha(bytes),pin.app,'wrong fixed app');const s=bytes.toString('utf8'),end='  renderAchievements();\n}\nbootstrap();\n';assert.ok(s.endsWith(end));assert.equal(s.split('  const onAchievementsFilter=()=>{state.achLimit=120;el(\'batchResult\').replaceChildren();renderAchievements();};').length,2);return Buffer.from(s.slice(0,-end.length)+FILTER_HOOK+end);}
function walk(root,dir=root){return readdirSync(dir).flatMap(n=>{const p=join(dir,n),st=lstatSync(p);assert.ok(!st.isSymbolicLink(),'symlink');if(st.isDirectory())return walk(root,p);assert.ok(st.isFile(),'nonregular');return [relative(root,p).split('\\').join('/')];});}
export function verifyBase(root,manifestBytes,version){const pin=bases[version];assert.ok(pin);assert.equal(sha(manifestBytes),pin.manifest,'wrong fixed manifest');const m=JSON.parse(manifestBytes.toString('utf8'));assert.equal(m.writer,'OFF');assert.equal(m.entries,4146);assert.equal(m.webp,4076);const paths=walk(root).sort();assert.deepEqual(paths,Object.keys(m.files).sort());let bytes=0;for(const p of paths){const b=readFileSync(join(root,p));assert.equal(b.length,m.files[p].bytes,p);assert.equal(sha(b),m.files[p].sha256,p);bytes+=b.length;}assert.equal(bytes,m.bytes);assert.equal(paths.filter(p=>p.endsWith('.webp')).length,4076);assert.equal(m.files['index.html'].sha256,INDEX);assert.equal(m.files['src/app.js'].sha256,pin.app);return m;}
export function prepare(root,manifestBytes,bundlePath,out,version){const m=verifyBase(root,manifestBytes,version);assert.ok(!existsSync(out),'fresh delta only');const base=realpathSync(root),bundleDir=realpathSync(dirname(bundlePath)),target=join(realpathSync(dirname(out)),out.split(/[\\/]/).at(-1));const outside=p=>{const r=relative(p,target);return r==='..'||r.startsWith('../')||r.startsWith('..\\')||isAbsolute(r);};assert.ok(outside(base)&&outside(bundleDir),'delta outside inputs');assert.deepEqual(walk(bundleDir).sort(),['product-filters.mjs']);const bundle=readFileSync(bundlePath);assert.ok(bundle.length>0&&bundle.length<512*1024,'bundle bound');assert.ok(!bundle.toString('utf8').includes('sourceMappingURL='));assert.ok(!Object.hasOwn(m.files,'src/product-filters.mjs'));const app=patchFilters(readFileSync(join(root,'src/app.js')),version);mkdirSync(join(out,'src'),{recursive:true});writeFileSync(join(out,'src/app.js'),app);writeFileSync(join(out,'src/product-filters.mjs'),bundle);const result={schema:'HKIA.ProductFiltersDelta.1',version,baseManifestSha256:bases[version].manifest,writer:'OFF_UNCHANGED',baseEntries:4146,unchanged:4145,changes:{'src/app.js':{kind:'MOD',before:bases[version].app,after:sha(app),bytes:app.length},'src/product-filters.mjs':{kind:'ADD',after:sha(bundle),bytes:bundle.length}},note:'Independent candidate. Compose with tab hook only through 00 exact-base integration; never replace an existing tab delta.'};writeFileSync(join(out,'delta-manifest.json'),JSON.stringify(result,null,2)+'\n');return result;}
if(process.argv[1]&&resolve(process.argv[1])===resolve(fileURLToPath(import.meta.url))){const [root,manifest,bundle,out,version]=process.argv.slice(2);assert.ok(root&&manifest&&bundle&&out&&version);console.log(JSON.stringify(prepare(resolve(root),readFileSync(manifest),resolve(bundle),resolve(out),version)));}
